import * as zod from 'zod'

/**
 * チケットの一覧を取得します。複数の条件を組み合わせて、フィルタ可能です。
 *
 * 注意1：パフォーマンス上の理由から、チケットの一覧取得ではフォームの入力や承認経路などはレスポンスに含まれません。
 * より詳細なチケット情報を取得したい場合は、チケットを一件だけ取得するAPIをで取得してください。
 *
 * 注意2：APIを実行するユーザーが閲覧可能なチケットのみ取得可能です。
 * テナント内のすべてのチケットを対象としたい場合、APIを実行するユーザーがチケットの管理権限（閲覧）を持っている必要があります。
 * @summary チケット一覧を取得
 */
export const listTicketsQueryPageDefault = 1

export const listTicketsQueryPerPageDefault = 25
export const listTicketsQueryPerPageMax = 100

export const listTicketsQuerySortByRegExp = new RegExp(
  '^(createdAt|updatedAt)(-asc|-desc)?$',
)

export const ListTicketsQueryParams = zod.object({
  page: zod
    .number()
    .min(1)
    .default(listTicketsQueryPageDefault)
    .describe('ページ'),
  perPage: zod
    .number()
    .min(1)
    .max(listTicketsQueryPerPageMax)
    .default(listTicketsQueryPerPageDefault)
    .describe('1ページあたりの件数'),
  sortBy: zod
    .string()
    .regex(listTicketsQuerySortByRegExp)
    .optional()
    .describe(
      'ソート対象のフィールドと順序。指定可能なフィールド: createdAt, updatedAt',
    ),
  status: zod
    .union([
      zod.enum([
        'draft',
        'in_progress',
        'rejected',
        'completed',
        'denied',
        'archived',
      ]),
      zod.array(
        zod.enum([
          'draft',
          'in_progress',
          'rejected',
          'completed',
          'denied',
          'archived',
        ]),
      ),
    ])
    .optional()
    .describe('ステータスの配列'),
  subStatusIds: zod
    .array(zod.uuid())
    .optional()
    .describe('サブステータスのUUIDの配列'),
  workflowId: zod.string().optional().describe('ワークフローのUUID'),
  authorId: zod.string().optional().describe('申請者のUUID'),
  authorTeamFullName: zod
    .string()
    .optional()
    .describe('申請時に選択したチームの上位組織を含む名前'),
  ticketNumber: zod.string().optional().describe('チケット番号'),
  createdAtStart: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('作成日時の起点'),
  createdAtEnd: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('作成日時の終点'),
  updatedAtStart: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('更新日時の起点'),
  updatedAtEnd: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('更新日時の終点'),
  openedAtStart: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('申請日時の起点'),
  openedAtEnd: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('申請日時の終点'),
  completedAtStart: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('完了日時の起点'),
  completedAtEnd: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('完了日時の終点'),
  archivedAtStart: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('アーカイブ日時の起点'),
  archivedAtEnd: zod
    .union([zod.unknown(), zod.unknown()])
    .optional()
    .describe('アーカイブ日時の終点'),
  assigneeUserId: zod
    .uuid()
    .optional()
    .describe('承認者のUUID。assigneeStatusとセットで指定してください。'),
  assigneeStatus: zod
    .array(zod.enum(['all', 'current', 'approved']))
    .optional()
    .describe('承認者の状態。assigneeUserIdとセットで指定してください。'),
  stepTitle: zod.string().optional().describe('現在の承認ステップ名'),
})

